<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Staff {
    public static function preverify(\PDO $p,int $actor,array $d,bool $sendInvitation=true): int {
        return Core::tx($p,function()use($p,$actor,$d,$sendInvitation){if(empty($d['organisation_id'])){$d['organisation_id']=Database::query($p,'SELECT s.organisation_id FROM staff_profiles s JOIN users u ON u.staff_identity_id=s.staff_identity_id WHERE u.id=? AND u.is_active=1',[$actor])->fetchColumn()?:Database::query($p,"SELECT setting_value FROM system_settings WHERE setting_key='registration_default_pkd'")->fetchColumn();}if(empty($d['organisation_id']))throw new \RuntimeException('Organisasi Admin/portal belum ditetapkan.');$org=Core::id($d['organisation_id']??'');Authorization::require($p,$actor,'core.staff.manage',$org);$name=Core::text($d['full_name']??'');$email=Core::email($d['official_email']??'');
            $matches=Database::query($p,"SELECT DISTINCT s.staff_identity_id,s.full_name,s.organisation_id,s.official_email,u.id AS user_id FROM staff_profiles s LEFT JOIN users u ON u.staff_identity_id=s.staff_identity_id LEFT JOIN staff_email_contacts c ON c.staff_identity_id=s.staff_identity_id AND c.email=? AND c.status IN ('PENDING_ADMIN_APPROVAL','APPROVED') WHERE s.official_email=? OR u.email=? OR c.id IS NOT NULL FOR UPDATE",[$email,$email,$email])->fetchAll();
            if($matches){if(count($matches)!==1)throw new \RuntimeException('E-mel mempunyai rekod bercanggah; semakan identiti Admin diperlukan. Tiada akaun diubah.');$existing=$matches[0];$existingOrg=Core::id($existing['organisation_id']);Authorization::require($p,$actor,'core.staff.manage',$existingOrg);if(mb_strtolower(trim($existing['full_name']))!==mb_strtolower(trim($name)))throw new \InvalidArgumentException('E-mel sudah dipautkan tetapi nama tidak sepadan. Gunakan semakan profil sedia ada; jangan cipta akaun baharu.');$existingId=(int)$existing['staff_identity_id'];if($existing['user_id']){Audit::record($p,'staff.existing_identity_resolved',$actor,$existingOrg,(string)$existingId,'core',null,null,['account_preserved'=>true,'invitation_sent'=>false]);return $existingId;}if($existing['official_email']!==$email||Database::query($p,'SELECT status FROM staff_registry WHERE staff_identity_id=?',[$existingId])->fetchColumn()!=='PRE_VERIFIED')throw new \RuntimeException('Identiti sedia ada memerlukan semakan registry; tiada jemputan atau akaun baharu dicipta.');if($sendInvitation)Accounts::invite($p,$actor,$existingId,'Admin repeat registration; reuse preverified Staff ID');return $existingId;}
            if(Database::query($p,'SELECT 1 FROM staff_profiles WHERE official_email=?',[$email])->fetchColumn()||Database::query($p,'SELECT 1 FROM users WHERE email=?',[$email])->fetchColumn())throw new \InvalidArgumentException('E-mel telah mempunyai rekod.');
            $fields=self::employment($p,$d,$org);if(RegistrationMaster::profileReady($p)&&Database::query($p,"SELECT 1 FROM staff_email_contacts WHERE email=? AND status IN ('PENDING_ADMIN_APPROVAL','APPROVED')",[$email])->fetchColumn())throw new \InvalidArgumentException('E-mel mempunyai persistent identity.');Database::query($p,'INSERT INTO staff_identities(identity_uuid) VALUES(?)',[Core::uuid()]);$id=(int)$p->lastInsertId();Database::query($p,'INSERT INTO staff_profiles(staff_identity_id,full_name,official_email,organisation_id,profession_id,position_id,grade_id,employment_status_id,facility_id,unit_id) VALUES(?,?,?,?,?,?,?,?,?,?)',[$id,$name,$email,$org,...$fields]);Database::query($p,'INSERT INTO staff_registry(staff_identity_id,verified_by) VALUES(?,?)',[$id,$actor]);Database::query($p,'INSERT INTO employment_history(staff_identity_id,effective_from,organisation_id,position_id,grade_id,change_reason,changed_by) VALUES(?,UTC_DATE(),?,?,?,?,?)',[$id,$org,$fields[1],$fields[2],'Pre-verified registry entry',$actor]);Audit::record($p,'staff.pre_verified',$actor,$org,(string)$id,'core',null,null,['full_name'=>$name,'official_email'=>$email,'organisation_id'=>$org]);if($sendInvitation)Accounts::issue($p,'claim',$email,$id);return $id;});
    }
    public static function validateRow(\PDO $p,int $actor,array $d):void {
        $org=Core::id($d['organisation_id']??'');Authorization::require($p,$actor,'core.registry.import',$org);Authorization::require($p,$actor,'core.staff.manage',$org);Core::text($d['full_name']??'');$email=Core::email($d['official_email']??'');self::employment($p,$d,$org);if(RegistrationMaster::profileReady($p)&&Database::query($p,"SELECT 1 FROM staff_email_contacts WHERE email=? AND status IN ('PENDING_ADMIN_APPROVAL','APPROVED')",[$email])->fetchColumn())throw new \InvalidArgumentException('E-mel mempunyai persistent identity.');if(Database::query($p,'SELECT 1 FROM staff_profiles WHERE official_email=?',[$email])->fetchColumn()||Database::query($p,'SELECT 1 FROM users WHERE email=?',[$email])->fetchColumn())throw new \InvalidArgumentException('E-mel telah mempunyai rekod.');
    }
    private static function employment(\PDO $p,array $d,int $org): array {
        if(!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND is_active=1',[$org])->fetchColumn())throw new \InvalidArgumentException('Organisasi tidak aktif.');$v=[];if(RegistrationMaster::ready($p))RegistrationMaster::employment($p,$d);foreach(['profession','position','grade','employment_status'] as $c)$v[]=MasterData::validate($p,Core::id($d[$c.'_id']??null,true),$c);
        $facility=Core::id($d['facility_id']??null,true);$unit=Core::id($d['unit_id']??null,true);if($unit===null&&Database::query($p,"SELECT 1 FROM organisations WHERE id=? AND type='unit'",[$org])->fetchColumn())$unit=$org;
        if($facility!==null&&!Database::query($p,"SELECT 1 FROM organisations o JOIN organisation_hierarchy h ON h.ancestor_id=o.id WHERE o.id=? AND o.type NOT IN ('national','state','pkd','unit') AND o.is_active=1 AND h.descendant_id=?",[$facility,$org])->fetchColumn())throw new \InvalidArgumentException('Fasiliti mesti induk organisasi staf.');
        if($unit!==null&&($unit!==$org||!Database::query($p,"SELECT 1 FROM organisations WHERE id=? AND type='unit' AND is_active=1",[$unit])->fetchColumn()))throw new \InvalidArgumentException('Unit mesti sama dengan organisasi staf.');return [...$v,$facility,$unit];
    }
    public static function get(\PDO $p,int $actor,int $id): array {
        $r=Database::query($p,'SELECT p.*,s.identity_uuid,u.id AS user_id,u.is_active,u.username,u.email,u.email_verified_at FROM staff_profiles p JOIN staff_identities s ON s.id=p.staff_identity_id LEFT JOIN users u ON u.staff_identity_id=p.staff_identity_id WHERE p.staff_identity_id=?',[$id])->fetch();if(!$r)throw new \InvalidArgumentException('Rekod tidak wujud.');if((int)($r['user_id']??0)!==$actor)Authorization::require($p,$actor,'core.staff.view',$r['organisation_id']===null?null:(int)$r['organisation_id']);if((int)($r['user_id']??0)!==$actor&&!Authorization::allowed($p,$actor,'core.staff.private_address',$r['organisation_id']===null?null:(int)$r['organisation_id']))$r['contact_address']=null;return $r;
    }
    public static function edit(\PDO $p,int $actor,int $id,array $d): void {
        Core::tx($p,function()use($p,$actor,$id,$d){$r=self::get($p,$actor,$id);Database::query($p,'SELECT staff_identity_id FROM staff_profiles WHERE staff_identity_id=? FOR UPDATE',[$id]);$self=(int)($r['user_id']??0)===$actor;$org=$r['organisation_id']===null?null:(int)$r['organisation_id'];if(!$self)Authorization::require($p,$actor,'core.staff.manage',$org);
            $name=Core::text($d['full_name']??$r['full_name']);$phone=RegistrationMaster::phone(Core::text($d['phone']??$r['phone']??'',30,false));$address=Core::text($r['contact_address']??'',1000,false);if(isset($d['contact_address'])&&$d['contact_address']!==$address)throw new \InvalidArgumentException('Gunakan borang alamat berstruktur protected.');Database::query($p,'UPDATE staff_profiles SET full_name=?,phone=? WHERE staff_identity_id=?',[$name,$phone,$id]);if(RegistrationMaster::profileReady($p))Database::query($p,'INSERT INTO staff_profile_extensions(staff_identity_id,updated_by) VALUES(?,?) ON DUPLICATE KEY UPDATE updated_by=VALUES(updated_by),updated_at=UTC_TIMESTAMP()',[$id,$actor]);
            if(isset($d['identification_number'])&&$d['identification_number']!==''){if(!Authorization::allowed($p,$actor,'core.identification.view',$org))throw new \RuntimeException('Akses nombor pengenalan tidak dibenarkan.');Database::query($p,'UPDATE staff_profiles SET identification_cipher=? WHERE staff_identity_id=?',[Crypto::seal(Core::text($d['identification_number'],100)),$id]);}
            if(!$self&&isset($d['official_email'])&&$d['official_email']!==$r['official_email']){if($r['user_id'])throw new \InvalidArgumentException('E-mel akaun mesti ditukar melalui pengesahan pemilikan.');$email=Core::email($d['official_email']);if(Database::query($p,'SELECT 1 FROM staff_profiles WHERE official_email=? AND staff_identity_id<>?',[$email,$id])->fetchColumn()||Database::query($p,'SELECT 1 FROM users WHERE email=?',[$email])->fetchColumn())throw new \InvalidArgumentException('E-mel telah mempunyai rekod.');Database::query($p,'UPDATE staff_profiles SET official_email=? WHERE staff_identity_id=?',[$email,$id]);Database::query($p,"INSERT INTO staff_registry(staff_identity_id,verified_by) VALUES(?,?) ON DUPLICATE KEY UPDATE verified_by=VALUES(verified_by),verified_at=UTC_TIMESTAMP()",[$id,$actor]);Database::query($p,"UPDATE account_tokens SET used_at=UTC_TIMESTAMP() WHERE staff_identity_id=? AND purpose='claim' AND used_at IS NULL",[$id]);}
            $after=['full_name'=>$name,'phone'=>$phone,'official_email'=>Database::query($p,'SELECT official_email FROM staff_profiles WHERE staff_identity_id=?',[$id])->fetchColumn()];Audit::record($p,'profile.updated',$actor,$org,(string)$id,'core',Core::text($d['reason']??'Profile update',500),array_diff_key($r,array_flip(['contact_address','identification_cipher'])),$after);});
    }
    public static function employmentChange(\PDO $p,int $actor,int $id,array $d): void {
        Core::tx($p,function()use($p,$actor,$id,$d){$r=self::get($p,$actor,$id);Database::query($p,'SELECT staff_identity_id FROM staff_profiles WHERE staff_identity_id=? FOR UPDATE',[$id]);$old=$r['organisation_id']===null?null:(int)$r['organisation_id'];$org=Core::id($d['organisation_id']??'');Authorization::require($p,$actor,'core.staff.manage',$old);Authorization::require($p,$actor,'core.staff.manage',$org);$fields=self::employment($p,$d,$org);if((int)($r['user_id']??0)===$actor&&($fields[0]!==$r['profession_id']||$fields[1]!==$r['position_id']||$fields[2]!==$r['grade_id']))throw new \RuntimeException('Self-verification gred/profesion ditolak.');$reason=Core::text($d['reason']??'',500);$date=Core::text($d['effective_from']??'',10);$dt=\DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$date>gmdate('Y-m-d'))throw new \InvalidArgumentException('Tarikh kuat kuasa mesti sah dan tidak melebihi hari ini.');$last=Database::query($p,'SELECT * FROM employment_history WHERE staff_identity_id=? AND effective_until IS NULL ORDER BY id DESC LIMIT 1 FOR UPDATE',[$id])->fetch();if($last&&$last['effective_from']!==null&&$date<$last['effective_from'])throw new \InvalidArgumentException('Tarikh bertindih dengan rekod semasa.');if($last)Database::query($p,'UPDATE employment_history SET effective_until=? WHERE id=?',[$date,$last['id']]);Database::query($p,'INSERT INTO employment_history(staff_identity_id,effective_from,previous_organisation_id,organisation_id,position_id,grade_id,change_reason,changed_by) VALUES(?,?,?,?,?,?,?,?)',[$id,$date,$old,$org,$fields[1],$fields[2],$reason,$actor]);Database::query($p,'UPDATE staff_profiles SET organisation_id=?,profession_id=?,position_id=?,grade_id=?,employment_status_id=?,facility_id=?,unit_id=? WHERE staff_identity_id=?',[$org,...$fields,$id]);
            // Ordinary staff scopes follow their current workplace; admin delegation must be reviewed separately.
            if($r['user_id']&&$old!==$org){$assign=Database::query($p,"SELECT a.* FROM user_role_assignments a JOIN roles rr ON rr.id=a.role_id WHERE a.user_id=? AND rr.code='staff'",[$r['user_id']])->fetchAll();foreach($assign as $a){Database::query($p,'INSERT INTO role_assignment_history(user_id,actor_id,action,assignment_json,reason) VALUES(?,?,?,?,?)',[$r['user_id'],$actor,'TRANSFER',json_encode($a,JSON_THROW_ON_ERROR),$reason]);Database::query($p,'DELETE FROM user_role_assignments WHERE id=?',[$a['id']]);}Database::query($p,"INSERT INTO user_role_assignments(user_id,role_id,organisation_id,module_code) SELECT ?,id,?,'core' FROM roles WHERE code='staff'",[$r['user_id'],$org]);Database::query($p,'UPDATE users SET credential_revision=credential_revision+1 WHERE id=?',[$r['user_id']]);}
            if($r['user_id'])ModuleAccess::sync($p,(int)$r['user_id'],$org,$actor);
            Audit::record($p,'employment.changed',$actor,$org,(string)$id,'core',$reason,array_diff_key($r,array_flip(['contact_address','identification_cipher'])),['organisation_id'=>$org,'effective_from'=>$date,'position_id'=>$fields[1],'grade_id'=>$fields[2]]);});
    }
    public static function credential(\PDO $p,int $actor,int $id,array $d):void {
        Core::tx($p,function()use($p,$actor,$id,$d){$r=self::get($p,$actor,$id);if((int)($r['user_id']??0)!==$actor)Authorization::require($p,$actor,'core.staff.manage',$r['organisation_id']===null?null:(int)$r['organisation_id']);$reg=MasterData::validate($p,Core::id($d['regulator_id']??''),'regulator');$num=Core::text($d['registration_number']??'',100);Database::query($p,'INSERT INTO professional_credentials(staff_identity_id,regulator_id,registration_number,additional_credentials) VALUES(?,?,?,?)',[$id,$reg,$num,Core::text($d['additional_credentials']??'',500,false)]);Audit::record($p,'professional.updated',$actor,$r['organisation_id']===null?null:(int)$r['organisation_id'],(string)$id,'core',null,null,['regulator_id'=>$reg,'registration_number'=>$num,'additional_credentials'=>Core::text($d['additional_credentials']??'',500,false)]);});
    }
    public static function registryStatus(\PDO $p,int $actor,int $id,string $status,string $reason):void {
        if(!in_array($status,['PRE_VERIFIED','INACTIVE'],true))throw new \InvalidArgumentException('Status registry tidak sah.');Core::tx($p,function()use($p,$actor,$id,$status,$reason){$r=self::get($p,$actor,$id);Authorization::require($p,$actor,'core.staff.manage',$r['organisation_id']===null?null:(int)$r['organisation_id']);if($r['user_id'])throw new \RuntimeException('Akaun sudah dituntut; gunakan status akaun.');$old=Database::query($p,'SELECT * FROM staff_registry WHERE staff_identity_id=? FOR UPDATE',[$id])->fetch();if(!$old)throw new \RuntimeException('Lengkapkan e-mel dan pengesahan registry dahulu.');Database::query($p,'UPDATE staff_registry SET status=?,verified_by=?,verified_at=UTC_TIMESTAMP() WHERE staff_identity_id=?',[$status,$actor,$id]);Database::query($p,"UPDATE account_tokens SET used_at=UTC_TIMESTAMP() WHERE staff_identity_id=? AND purpose='claim' AND used_at IS NULL",[$id]);Audit::record($p,'registry.status_changed',$actor,$r['organisation_id']===null?null:(int)$r['organisation_id'],(string)$id,'core',Core::text($reason,500),$old,['status'=>$status]);});
    }
    public static function accountStatus(\PDO $p,int $actor,int $user,bool $active,string $reason):void {
        // Serialize last-super-admin invariant across concurrent administrative actions.
        if((int)Database::query($p,"SELECT GET_LOCK(CONCAT('ep_accounts_',LEFT(SHA2(DATABASE(),256),40)),5)")->fetchColumn()!==1)throw new \RuntimeException('Cuba semula.');
        try{Core::tx($p,function()use($p,$actor,$user,$active,$reason){$r=Database::query($p,'SELECT u.*,p.organisation_id FROM users u JOIN staff_profiles p ON p.staff_identity_id=u.staff_identity_id WHERE u.id=? FOR UPDATE',[$user])->fetch();if(!$r)throw new \InvalidArgumentException('Akaun tidak wujud.');$org=$r['organisation_id']===null?null:(int)$r['organisation_id'];Authorization::require($p,$actor,'core.users.manage',$org);$isSuper=(bool)Database::query($p,"SELECT 1 FROM user_role_assignments a JOIN roles r ON r.id=a.role_id WHERE a.user_id=? AND r.code='super_admin'",[$user])->fetchColumn();if($isSuper&&!Authorization::super($p,$actor))throw new \RuntimeException('Akses tidak dibenarkan.');if(!Authorization::super($p,$actor)){foreach(Database::query($p,'SELECT r.code FROM user_role_assignments a JOIN roles r ON r.id=a.role_id WHERE a.user_id=?',[$user])->fetchAll() as $rr)if(!isset(Roles::RANK[$rr['code']])||Roles::RANK[$rr['code']]>=Roles::level($p,$actor,$org))throw new \RuntimeException('Status akaun memerlukan pentadbir lebih tinggi.');}if(!$active&&$isSuper&&$r['is_active']&&Roles::activeSupers($p)<=1)throw new \RuntimeException('Super Admin terakhir mesti dikekalkan.');Database::query($p,'UPDATE users SET is_active=?,credential_revision=credential_revision+1 WHERE id=?',[$active?1:0,$user]);Audit::record($p,$active?'user.activated':'user.deactivated',$actor,$org,(string)$user,'core',Core::text($reason,500),['is_active'=>$r['is_active']],['is_active'=>$active]);});}finally{Database::query($p,"SELECT RELEASE_LOCK(CONCAT('ep_accounts_',LEFT(SHA2(DATABASE(),256),40)))");}
    }
}
